const b=$json.body??$json;
const str=(k)=>String(b[k]??'').trim();
const action=str('action')||'chat',message=str('message'),enquiryId=str('enquiry_id'),contactId=str('contact_id'),serviceSlug=str('service_slug'),serviceName=str('service_name'),date=str('date'),time=str('time'),fullName=str('full_name'),email=str('email').toLowerCase();
const sessionId=(str('session_id')||('demo-'+Date.now())).replace(/[^a-zA-Z0-9_-]/g,'').slice(0,80);
let history=[];try{history=JSON.parse(String(b.history??'[]'));if(!Array.isArray(history))history=[]}catch{}
let choiceData=[];try{choiceData=JSON.parse(String(b.choice_data??'[]'));if(!Array.isArray(choiceData))choiceData=[]}catch{}
let slots=[];try{slots=JSON.parse(String(b.slots??'[]'));if(!Array.isArray(slots))slots=[]}catch{}
if(!history.length)history=[{who:'assistant',text:'Hi 👋 Welcome to Favfare. What would you like help with today?'}];
function nextOpen(){const x=new Date();for(let i=1;i<8;i++){const y=new Date(x);y.setUTCDate(y.getUTCDate()+i);const d=y.getUTCDay();if(d>=1&&d<=6)return y.toISOString().slice(0,10)}return x.toISOString().slice(0,10)}
const useDate=date||nextOpen();
let api_url,payload;
if(action==='chat'){api_url='https://shftukueyostzbyqxmqw.supabase.co/functions/v1/favfare-demo-assistant';payload={action:'chat',message,history};}
else if(action==='service_selected'){api_url=$env.FAVFARE_DATA_GATEWAY_URL;payload={action:'quote_and_capture',message:message||('I am interested in '+serviceName),service_slug:serviceSlug,full_name:'WhatsApp Patient',phone:'+2348000000200',whatsapp_id:'favfare-'+sessionId};}
else if(action==='availability'){api_url=$env.FAVFARE_DATA_GATEWAY_URL;payload={action:'availability_for_date',date:useDate,enquiry_id:enquiryId};}
else if(action==='request_booking'){api_url=$env.FAVFARE_DATA_GATEWAY_URL;payload={action:'request_booking',enquiry_id:enquiryId,preferred_date:useDate,preferred_time:time};}
else if(action==='capture_email'){api_url='https://shftukueyostzbyqxmqw.supabase.co/functions/v1/favfare-demo-contact';payload={contact_id:contactId,full_name:fullName,phone:'+2348000000200',email};}
else if(action==='booking_status'){api_url=$env.FAVFARE_CRM_GATEWAY_URL;payload={action:'enquiry_detail',enquiry_id:enquiryId};}
else{api_url='https://shftukueyostzbyqxmqw.supabase.co/functions/v1/favfare-demo-assistant';payload={action:'noop'};}
return[{json:{action,message,enquiry_id:enquiryId,contact_id:contactId,service_slug:serviceSlug,service_name:serviceName,date:useDate,time,full_name:fullName,email,session_id:sessionId,history,choice_data:choiceData,slots,api_url,payload}}];

const d=$json??{},c=$('Normalize V4').first().json;
const esc=v=>String(v??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
let h=Array.isArray(c.history)?[...c.history]:[];const say=(who,text)=>{if(text)h.push({who,text:String(text)})};
const hidden=(n,v)=>'<input type=\"hidden\" name=\"'+esc(n)+'\" value=\"'+esc(v)+'\">';
const effE=(c.action==='service_selected'&&d.enquiry_id)?String(d.enquiry_id):c.enquiry_id,effC=(c.action==='service_selected'&&d.contact_id)?String(d.contact_id):c.contact_id;
const state=(over={})=>{const s={session_id:c.session_id,enquiry_id:effE,contact_id:effC,service_slug:c.service_slug,service_name:c.service_name,date:c.date,time:c.time,full_name:c.full_name,email:c.email,choice_data:JSON.stringify(c.choice_data||[]),slots:JSON.stringify(c.slots||[]),...over};return hidden('history',JSON.stringify(h))+Object.entries(s).map(([k,v])=>hidden(k,v??'')).join('')};
const form=(action,label,over={},cls='wa-reply')=>'<form method=\"post\" action=\"/webhook/favfare-demo/patient-action-v4\">'+hidden('action',action)+state(over)+'<button class=\"'+cls+'\">'+esc(label)+'</button></form>';
const composer=()=>'<form class=\"composer\" method=\"post\" action=\"/webhook/favfare-demo/patient-action-v4\">'+hidden('action','chat')+state()+'<input name=\"message\" placeholder=\"Message\" autocomplete=\"off\" required><button aria-label=\"send\">➤</button></form>';
const pretty=iso=>new Date(iso+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const choiceForms=arr=>arr.map(x=>form('service_selected',x.label,{service_slug:x.slug,service_name:x.label,message:'I am interested in '+x.label},'wa-reply')).join('');
const listOpen=(action,label,data)=>form(action,'☰  '+label,data,'wa-list-button');
let controls='',sheet='',allowComposer=true;
if(c.action==='chat'){say('patient',c.message);say('assistant',d.reply||'Tell me a little more about what you would like help with.');const choices=Array.isArray(d.choices)?d.choices:[];if(d.handoff){controls='<div class=\"wa-buttons\">'+form('chat','Talk to the clinic team',{message:'I want to speak to a staff member'})+'</div>';}else if(choices.length>0&&choices.length<=3){controls='<div class=\"wa-buttons\">'+choiceForms(choices)+'</div>';}else if(choices.length>3){controls='<div class=\"wa-buttons\">'+listOpen('show_service_list','View options',{choice_data:JSON.stringify(choices)})+'</div>';} }
else if(c.action==='show_service_list'){allowComposer=false;const choices=c.choice_data||[];sheet='<div class=\"sheet\"><div class=\"sheet-head\"><b>Choose a service</b><span>Favfare</span></div>'+choices.map(x=>'<div class=\"sheet-row\">'+form('service_selected',x.label+(x.description?' · '+x.description:''),{service_slug:x.slug,service_name:x.label,message:'I am interested in '+x.label},'sheet-btn')+'</div>').join('')+'<div class=\"sheet-cancel\">'+form('chat','Cancel',{message:'Show me something else'},'sheet-btn')+'</div></div>'; }
else if(c.action==='service_selected'){say('patient','I’m interested in '+c.service_name+'.');if(d.ok&&d.quote_allowed&&d.service){say('assistant',d.service.name+' is '+d.service.price_display+'. Would you like me to check the next available times?');controls='<div class=\"wa-buttons\">'+form('availability','Check availability')+form('chat','Ask a question',{message:'I have a question about '+c.service_name})+'</div>';}else{say('assistant','I can help with that, but I could not retrieve the current website price just now.');}}
else if(c.action==='availability'){say('patient','Yes, check availability.');const slots=Array.isArray(d.slots)?d.slots.slice(0,10):[];if(slots.length){say('assistant','I have availability on '+pretty(c.date)+'. Tap below to choose a time.');controls='<div class=\"wa-buttons\">'+listOpen('show_time_list','Choose a time',{slots:JSON.stringify(slots)})+'</div>';}else{say('assistant','I don’t have an open slot on that date. I can help you try another day.');}}
else if(c.action==='show_time_list'){allowComposer=false;const slots=c.slots||[];sheet='<div class=\"sheet\"><div class=\"sheet-head\"><b>Available times</b><span>'+esc(pretty(c.date))+'</span></div>'+slots.map(t=>'<div class=\"sheet-row\">'+form('choose_time',String(t).slice(0,5),{time:String(t).slice(0,5)},'sheet-btn')+'</div>').join('')+'<div class=\"sheet-cancel\">'+form('availability','Back',{},'sheet-btn')+'</div></div>'; }
else if(c.action==='choose_time'){say('patient',c.time);say('assistant','Great — '+c.time+' is available. What full name should I put on the booking?');controls='<form class=\"capture\" method=\"post\" action=\"/webhook/favfare-demo/patient-action-v4\">'+hidden('action','capture_name')+state()+'<input name=\"full_name\" placeholder=\"Full name\" autocomplete=\"name\" required><button>Continue</button></form>';allowComposer=false;}
else if(c.action==='capture_name'){say('patient',c.full_name);say('assistant','Thanks, '+c.full_name+'. What email should Favfare attach to the booking?');controls='<form class=\"capture\" method=\"post\" action=\"/webhook/favfare-demo/patient-action-v4\">'+hidden('action','capture_email')+state()+'<input type=\"email\" name=\"email\" placeholder=\"Email address\" required><button>Continue</button></form><div class=\"micro\">Your WhatsApp number is captured automatically in production.</div>';allowComposer=false;}
else if(c.action==='capture_email'){say('patient',c.email);if(d.ok){say('assistant','Perfect. I can book '+c.service_name+' for '+pretty(c.date)+' at '+c.time+'.');controls='<div class=\"summary\"><b>'+esc(c.service_name)+'</b><span>'+esc(pretty(c.date))+' · '+esc(c.time)+'</span><span>'+esc(c.full_name)+' · '+esc(c.email)+'</span></div><div class=\"wa-buttons\">'+form('request_booking','Confirm booking')+'</div>';allowComposer=false;}else{say('assistant','I could not save that email. Please try again.');}}
else if(c.action==='request_booking'){say('patient','Confirm booking');if(d.ok&&d.booking_status==='confirmed'){say('assistant',d.reply||('You’re booked for '+pretty(c.date)+' at '+c.time+'.'));say('assistant','You’re all set. The clinic team has been notified of the new booking.');controls='<div class=\"done-actions\"><a href=\"/webhook/favfare-demo/crm-ui\" target=\"_blank\">Open staff CRM ↗</a><a href=\"/webhook/favfare-demo/patient\">Start new demo</a></div>';allowComposer=false;}else{say('assistant','That time was just taken. I can show you the remaining available times.');controls='<div class=\"wa-buttons\">'+form('availability','Choose another time')+'</div>';}}
const bubbles=h.map(x=>'<div class=\"msg '+(x.who==='patient'?'out':'in')+'\"><div class=\"bubble\">'+esc(x.text)+'</div></div>').join('');
const html='<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Favfare WhatsApp Demo</title><style>*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#dfe8e3;color:#111;min-height:100vh;display:grid;place-items:center;padding:20px}.stage{width:min(980px,100%);display:grid;grid-template-columns:1fr 390px;gap:34px;align-items:center}.copy h1{font-size:40px;margin:8px 0}.copy p{color:#62706a;line-height:1.65;max-width:500px}.copy small{font-weight:800;letter-spacing:.14em;color:#47705e}.phone{height:760px;max-height:92vh;border-radius:26px;overflow:hidden;display:flex;flex-direction:column;background:#efeae2;box-shadow:0 25px 70px rgba(17,45,34,.22)}.bar{background:#075e54;color:white;padding:12px 14px;display:flex;gap:10px;align-items:center}.avatar{width:40px;height:40px;border-radius:50%;background:#fff;color:#075e54;display:grid;place-items:center;font-weight:900}.bar b{display:block}.bar span{font-size:11px;opacity:.8}.notice{font-size:10px;text-align:center;background:#fff6cb;color:#755d14;padding:6px}.chat{flex:1;overflow:auto;padding:15px 12px;background-image:radial-gradient(rgba(0,0,0,.025) 1px,transparent 1px);background-size:18px 18px}.msg{display:flex;margin:7px 0}.msg.out{justify-content:flex-end}.bubble{max-width:82%;padding:8px 10px;border-radius:8px;line-height:1.42;font-size:14px;box-shadow:0 1px 1px rgba(0,0,0,.1)}.in .bubble{background:#fff;border-top-left-radius:2px}.out .bubble{background:#d9fdd3;border-top-right-radius:2px}.controls{background:#f0f2f5;padding:8px}.wa-buttons{background:#fff;border-radius:8px;overflow:hidden;margin-bottom:7px;box-shadow:0 1px 1px rgba(0,0,0,.08)}.wa-buttons form{margin:0}.wa-reply,.wa-list-button{width:100%;border:0;border-top:1px solid #e6e9e7;background:#fff;color:#008069;padding:11px 12px;font-weight:650;text-align:center;cursor:pointer}.wa-buttons form:first-child .wa-reply,.wa-buttons form:first-child .wa-list-button{border-top:0}.composer{display:flex;gap:7px}.composer input,.capture input{flex:1;border:0;background:#fff;border-radius:22px;padding:11px 14px;outline:none}.composer button{width:43px;height:43px;border:0;border-radius:50%;background:#00a884;color:#fff}.capture{display:flex;gap:7px}.capture button{border:0;border-radius:20px;background:#00a884;color:#fff;padding:0 15px;font-weight:700}.micro{font-size:10px;color:#6e7b75;padding:5px 4px}.summary{background:#fff;padding:11px;border-radius:9px;margin-bottom:7px;display:grid;gap:3px}.summary span{font-size:12px;color:#67736d}.sheet{position:absolute;left:50%;bottom:0;transform:translateX(-50%);width:390px;max-width:100%;background:#fff;border-radius:20px 20px 0 0;box-shadow:0 -15px 45px rgba(0,0,0,.22);overflow:hidden;z-index:10}.sheet-head{padding:15px 16px;border-bottom:1px solid #eceeee}.sheet-head b{display:block}.sheet-head span{font-size:11px;color:#748079}.sheet-row form,.sheet-cancel form{margin:0}.sheet-btn{width:100%;border:0;background:#fff;text-align:left;padding:13px 16px;border-bottom:1px solid #eceeee;color:#202723;cursor:pointer}.sheet-cancel .sheet-btn{text-align:center;color:#008069;font-weight:700}.done-actions{display:grid;gap:7px}.done-actions a{display:block;text-align:center;text-decoration:none;padding:10px;border-radius:9px;background:#075e54;color:#fff;font-weight:700}.done-actions a:last-child{background:#fff;color:#075e54}.wrap{position:relative}.provider{font-size:10px;color:#77837d;margin-top:8px}@media(max-width:830px){.stage{grid-template-columns:1fr}.copy{display:none}.phone{height:88vh}.sheet{width:100%}}</style></head><body><div class=\"stage\"><div class=\"copy\"><small>BIZI SYSTEMS · FAVFARE DEMO</small><h1>Patient Assistant</h1><p>A conversational WhatsApp sales assistant using Favfare’s server-side service catalogue and live booking availability.</p><div class=\"provider\">Conversation provider: '+esc(d.provider||'deterministic tools')+'</div></div><div class=\"wrap\"><section class=\"phone\"><div class=\"bar\"><div class=\"avatar\">F</div><div><b>Favfare The Clinic</b><span>online</span></div></div><div class=\"notice\">Demo · valid free slots auto-confirm</div><div class=\"chat\">'+bubbles+'</div><div class=\"controls\">'+controls+(allowComposer?composer():'')+'</div></section>'+sheet+'</div></div></body></html>';return[{json:{html}}];
